export const maxAchievementScore = achievementCatalog.reduce((sum,medal)=>sum+medal.points,0);
const validDate = value=>typeof value==='string' && /^\d{4}-\d{2}-\d{2}$/.test(value) && Number.isFinite(Date.parse(value)) && new Date(value+'T12:00:00Z').toISOString().slice(0,10)===value;
const present = value=>typeof value==='string' && !!value.trim();
export function achievementFacts({sessions=[],programs=[],exercises=[],friends=[],comments=[],profile={},activeDays=0,sharedWorkouts=0,uid='',today=new Date().toISOString().slice(0,10)}={}) {
  const completed=[],keys=new Set();let sets=0,volume=0;
  for(const session of sessions) {
    if(session.status!=='completed' || !validDate(session.date) || session.date>today || !Array.isArray(session.items) || !Array.isArray(session.logs))continue;
    if(session.items.length>30 || session.logs.length>1230)continue;
    const counts=new Map(),performed=new Set((Array.isArray(session.simpleCompleted)?session.simpleCompleted:[]).filter(index=>Number.isInteger(index)&&present(session.items[index]?.name)&&Number.isInteger(session.items[index].sets)&&session.items[index].sets>=1&&session.items[index].sets<=20));
    for(const log of session.logs) {
      const item=session.items[log?.index];
      if(!item || !validWeightDetails(log) || !present(item.name) || !Number.isInteger(item.sets) || item.sets<1 || item.sets>20 || !Number.isInteger(log.index) || log.warmup || !Number.isInteger(log.reps) || log.reps<0 || log.reps>1000 ||
        (log.seconds!==undefined&&(!Number.isFinite(log.seconds)||log.seconds<0||log.seconds>7200)) ||
        ['quickResult','weightUnknown','warmup'].some(key=>log[key]!==undefined&&typeof log[key]!=='boolean') ||
        !Number.isFinite(log.weight) || log.weight<0 || log.weight>1000 || !(log.reps>0 || Number(log.seconds)>0))continue;
      performed.add(log.index);
      if(log.quickResult || log.dropOf!==undefined)continue;
      const count=counts.get(log.index)||0;
      if(!Number.isInteger(item.sets)||count>=Math.min(item.sets,20))continue;
      counts.set(log.index,count+1);sets++;
      if(!log.weightUnknown)volume+=totalWeight(log)*log.reps;
    }
    if(!performed.size && !(session.items.length===0&&present(session.description)&&!session.endedEarly))continue;
    completed.push(session);
    for(const index of performed) {
      const item=session.items[index], key=typeof item.exerciseId==='string'&&item.exerciseId?item.exerciseId:String(item.name||'').trim().toLocaleLowerCase('uk');
      if(key)keys.add(key);
    }
  }
  const weeks=[...new Set(completed.map(s=>{const date=new Date(s.date+'T00:00:00Z');return date.getTime()/86400000-(date.getUTCDay()+6)%7;}))].sort((a,b)=>a-b);
  let bestStreak=0,run=0,last;
  for(const week of weeks){run=week===last+7?run+1:1;bestStreak=Math.max(bestStreak,run);last=week;}
  return {workouts:completed.length,sets,volume:Math.round(volume),bestStreak,variety:keys.size,sharedWorkouts:Math.max(0,Math.floor(Number(sharedWorkouts)||0)),
    programs:programs.filter(p=>!p.archived && !p.id?.startsWith('demo-') && Array.isArray(p.days) && p.days.some(day=>day&&((Array.isArray(day.items)&&day.items.length)||present(day.description)))).length,
    planned:sessions.filter(s=>['planned','active','completed'].includes(s.status)&&(s.status==='planned'&&validDate(s.date)||validDate(s.plannedDate))).length,
    exercises:exercises.filter(e=>!e.archived && present(e.name)).length,
    friends:new Set(friends.filter(f=>f.status==='accepted'&&Array.isArray(f.members)&&f.members.includes(uid)).map(f=>f.members.find(id=>id!==uid)).filter(Boolean)).size,
    profileComplete:Number(present(profile.photo)&&present(profile.bio)&&present(profile.location)),
    comments:comments.filter(c=>c.authorId===uid&&present(c.text)).length,
    activeDays:Math.max(0,Math.min(90,Number.isFinite(activeDays)?Math.floor(activeDays):0)),
  };
}
export function evaluateAchievements(facts={},manualIds=[]) {
  const earnedIds=achievementCatalog.filter(medal=>manualIds.includes(medal.id)||!medal.manualOnly&&Number.isFinite(facts[medal.metric])&&facts[medal.metric]>=medal.target).map(medal=>medal.id);
  return {earnedIds,score:achievementCatalog.filter(medal=>earnedIds.includes(medal.id)).reduce((sum,medal)=>sum+medal.points,0)};
}
export function achievementSelection(selectedIds,earnedIds) {
  if(!Array.isArray(selectedIds)||selectedIds.length>3||new Set(selectedIds).size!==selectedIds.length||selectedIds.some(id=>!earnedIds.includes(id)||!achievementCatalog.some(medal=>medal.id===id)))
    throw Error('Обери до трьох різних зароблених медалей.');
  return [...selectedIds];
}
export function sessionAchievementSignature(session) {
  if(!session)return '';
  const planned=session.status==='planned'||['active','completed'].includes(session.status)&&!!session.plannedDate;
  return session.status==='completed'?JSON.stringify({planned,date:session.date,items:session.items,logs:session.logs,
    simpleCompleted:session.simpleCompleted,description:session.description,endedEarly:session.endedEarly,invitationId:session.invitationId,gymBroId:session.gymBroId}):String(planned);
}
export function sharedWorkoutCount(uid,sessions,invites,partners,today) {
  const own=new Map(sessions.map(session=>[session.id,session]));
  return new Set(invites.filter(invite=>{
    if(invite.status!=='accepted'||![invite.from,invite.to].includes(uid)||invite.from===invite.to)return false;
    const partner=invite.from===uid?invite.to:invite.from;
    const session=own.get(`invite_${invite.id}`),other=partners.get(`${partner}/${invite.id}`);
    return [session,other].every((entry,index)=>entry?.invitationId===invite.id&&entry.gymBroId===(index===0?partner:uid)&&entry.date===invite.date&&achievementFacts({sessions:[entry],today}).workouts===1);
  }).map(invite=>invite.id)).size;
}
